-- Jeu de données de DÉPANNAGE LaborScope : de vraies données ILOSTAT, en petite quantité.
-- Pas chargé par défaut : les données s'importent normalement depuis l'API ILOSTAT.
-- À utiliser si l'API est injoignable : python -m utils.reset_database --exemple
-- (exécuté juste après init_db.sql).
--
-- Contenu : 3 indicateurs, 6 pays (FRA, DEU, ESP, USA, BRA, ZAF), trimestres depuis 2023,
-- 5 professions pour l'emploi par profession (dont Total), 3 tranches d'âge pour les taux.
-- Extrait téléchargé depuis l'API ILOSTAT le 2026-11-20 avec la chaîne d'import du projet
-- (DataProcessing.fetch_data puis parse_data).
--
-- Pour l'ensemble des données : python -m fetcher.charger_donnees (complète cet extrait sans
-- créer de doublons, grâce aux INSERT ... ON CONFLICT des DAO).

SET search_path TO laborscope;

-- Indicateurs (mêmes valeurs que backend/src/config_import.py)
INSERT INTO indicateur (code, libelle, unite, frequence, nom_classif1) VALUES
    ('EMP_5EMP_SEX_OC2_NB_Q', 'Emploi par sexe et profession', 'milliers', 'Q', 'profession'),
    ('EMP_5WAP_SEX_AGE_RT_Q', 'Taux d''emploi par sexe et âge', '%', 'Q', 'tranche_age'),
    ('UNE_5EAP_SEX_AGE_RT_Q', 'Taux de chômage par sexe et par âge', '%', 'Q', 'tranche_age');

-- Pays
INSERT INTO pays (code_iso, nom) VALUES
    ('BRA', 'Brazil'),
    ('DEU', 'Germany'),
    ('ESP', 'Spain'),
    ('FRA', 'France'),
    ('USA', 'United States of America'),
    ('ZAF', 'South Africa');

